from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe.Strikes(-200, 200).Expiration(0, 730)
        )

        self.closes = RollingWindow[float](21)
        self.pending_entry_signal_time = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.held_contract = None
        self.entry_price = None
        self.expiry_date = None
        self.time_stop_date = None
        self.no_entry_date = None

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy_symbol, self.consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # A period consolidator aligned to exchange/New York time produces
        # regular-session bars ending 09:35, 09:40, etc.
        self.closes.Add(float(bar.Close))

        if self.closes.Count < 21:
            return

        current_fast = sum(self.closes[i] for i in range(0, 5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(0, 20)) / 20.0
        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        bar_end = bar.EndTime
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if eligible_time and bullish_cross:
            # OnData processes this against the Slice at this same bar close.
            self.pending_entry_signal_time = bar_end

    def OnData(self, data):
        today = self.Time.date()

        # Exercise or assignment can create an unexpected SPY holding.
        spy_quantity = self.Portfolio[self.spy_symbol].Quantity
        if spy_quantity != 0:
            if not self._has_open_orders(self.spy_symbol):
                self.Debug(
                    f"Unexpected SPY exercise/assignment position: "
                    f"{spy_quantity}; liquidating."
                )
                self.MarketOrder(self.spy_symbol, -spy_quantity)
            self.no_entry_date = today

        # Do not intentionally carry an option into its expiration date.
        if (
            self.held_contract is not None
            and self.expiry_date is not None
            and today >= self.expiry_date
            and self.Portfolio[self.held_contract].Invested
        ):
            self.no_entry_date = today
            self._submit_exit("expiration safeguard")

        # Evaluate the five-minute crossover only in the current Slice.
        signal_time = self.pending_entry_signal_time
        self.pending_entry_signal_time = None
        if signal_time is not None and signal_time == self.Time:
            self._try_enter(data)

        if self.held_contract is None:
            return

        if not self.Portfolio[self.held_contract].Invested:
            if self.entry_order_id is None:
                self._clear_position_state()
            return

        # The calendar immediately preceding expiry may be a weekend/holiday,
        # so use the preceding SPY trading day.
        if (
            self.time_stop_date == today
            and self.Time.time() == time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self.entry_price is None or self._exit_order_is_open():
            return

        midpoint = self._current_option_midpoint(data, self.held_contract)
        if midpoint is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _try_enter(self, data):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        if self.Portfolio[self.spy_symbol].Invested:
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        chain = data.OptionChains[self.option_symbol]
        minimum_expiry = today + timedelta(days=7)

        calls_by_expiry = {}
        for contract in chain:
            if contract.Right != OptionRight.Call:
                continue

            contract_expiry = contract.Expiry.date()
            if contract_expiry < minimum_expiry:
                continue

            if contract_expiry not in calls_by_expiry:
                calls_by_expiry[contract_expiry] = []
            calls_by_expiry[contract_expiry].append(contract)

        if not calls_by_expiry:
            self.Debug("Skipped entry: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = min(calls_by_expiry.keys())
        candidates = calls_by_expiry[selected_expiry]

        if not candidates:
            self.Debug("Skipped entry: selected expiration has no eligible calls.")
            return

        # No strike criterion was specified, so select the closest-to-ATM call
        # deterministically, breaking ties in favor of the lower strike.
        underlying_price = float(self.Securities[self.spy_symbol].Price)
        selected = min(
            candidates,
            key=lambda contract: (abs(float(contract.Strike) - underlying_price),
                                  float(contract.Strike))
        )

        self.entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, expiry "
            f"{selected_expiry}, strike {selected.Strike}."
        )

    def _current_option_midpoint(self, data, symbol):
        if symbol not in data.QuoteBars:
            return None

        quote = data.QuoteBars[symbol]
        if quote is None or quote.Bid is None or quote.Ask is None:
            return None

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return None

        return (bid + ask) / 2.0

    def _submit_exit(self, reason):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0 or self._exit_order_is_open():
            return

        # There should normally be no other exit order. Cancel any that remain
        # before submitting the required market liquidation.
        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, f"Replacing with {reason}")

        self.exit_order_id = self.MarketOrder(
            self.held_contract,
            -quantity,
            tag=reason
        ).OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract.Value}.")

    def _exit_order_is_open(self):
        if self.exit_order_id is None:
            return False

        return any(
            order.Id == self.exit_order_id
            for order in self.Transactions.GetOpenOrders(self.held_contract)
        )

    def _has_open_orders(self, symbol):
        return len(self.Transactions.GetOpenOrders(symbol)) > 0

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while not self.spy.Exchange.Hours.IsDateOpen(
            datetime.combine(candidate, time.min),
            False
        ):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiry_date = order_event.Symbol.ID.Date.date()
                self.time_stop_date = self._previous_spy_trading_day(
                    self.expiry_date
                )
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract.Value} at "
                    f"{self.entry_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry order closed without fill: {order_event.Message}")
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol.Value} at "
                    f"{float(order_event.FillPrice):.2f}."
                )
                self.exit_order_id = None
                self._clear_position_state()
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

    def _clear_position_state(self):
        self.held_contract = None
        self.entry_price = None
        self.expiry_date = None
        self.time_stop_date = None
        self.exit_order_id = None

