from AlgorithmImports import *
from collections import deque
from datetime import datetime, time, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self._five_minute_closes = deque(maxlen=20)
        self._previous_fast = None
        self._previous_slow = None
        self._pending_entry_signal = False

        self._entry_symbol = None
        self._entry_price = None
        self._held_contract = None
        self._held_expiry = None
        self._exit_order_id = None
        self._equity_cleanup_order_id = None
        self._block_entries_on_date = None

        self._five_minute = TradeBarConsolidator(timedelta(minutes=5))
        self._five_minute.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, self._five_minute)

    def _on_five_minute_bar(self, sender, bar):
        # With regular-hours minute SPY data, bars align as 09:30-09:35,
        # 09:35-09:40, and so on in New York time.
        self._five_minute_closes.append(float(bar.Close))

        if len(self._five_minute_closes) < 20:
            return

        closes = list(self._five_minute_closes)
        fast = sum(closes[-5:]) / 5.0
        slow = sum(closes) / 20.0

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        bar_end = bar.EndTime.time()
        in_entry_window = time(9, 45) <= bar_end <= time(14, 30)

        if bullish_cross and in_entry_window:
            self._pending_entry_signal = True

    def OnData(self, data):
        self._liquidate_unexpected_spy_position()
        self._handle_expiration_protection()
        self._handle_time_stop()
        self._handle_profit_target(data)

        if self._pending_entry_signal:
            self._pending_entry_signal = False
            self._try_enter(data)

    def _try_enter(self, data):
        if self._block_entries_on_date == self.Time.date():
            return

        if self._entry_symbol is not None or self._option_position_exists():
            return

        if not data.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        chain = data.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
        ]

        if not calls:
            self.Debug("Skipped entry: selected expiration has no eligible calls.")
            return

        # No strike constraint was specified, so choose the call nearest to
        # the current raw SPY price, with lower strike as a deterministic tie-break.
        underlying_price = float(self.Securities[self.spy].Price)
        if underlying_price <= 0:
            self.Debug("Skipped entry: SPY has no valid current price.")
            return

        selected = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike),
                contract.Symbol.Value
            )
        )

        self._entry_symbol = selected.Symbol
        self._entry_price = None
        self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, expiry {selected_expiry}, "
            f"strike {selected.Strike}."
        )

    def _handle_profit_target(self, data):
        if self._held_contract is None or self._entry_price is None:
            return

        if self._exit_order_id is not None:
            return

        if not self.Portfolio[self._held_contract].Invested:
            return

        if not data.OptionChains.ContainsKey(self.option_symbol):
            return

        held_contract = None
        for contract in data.OptionChains[self.option_symbol]:
            if contract.Symbol == self._held_contract:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50% profit target")

    def _handle_time_stop(self):
        if self._held_contract is None or self._held_expiry is None:
            return

        if self._exit_order_id is not None:
            return

        if not self.Portfolio[self._held_contract].Invested:
            return

        if self.Time.hour != 15 or self.Time.minute != 45:
            return

        if self.Time.date() == self._previous_trading_day(self._held_expiry):
            self._submit_exit("15:45 pre-expiration time stop")

    def _handle_expiration_protection(self):
        if self._held_contract is None or self._held_expiry is None:
            return

        if self.Time.date() < self._held_expiry:
            return

        self._block_entries_on_date = self.Time.date()

        if self.Portfolio[self._held_contract].Invested and self._exit_order_id is None:
            self._submit_exit("expiration protection")

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange = self.Securities[self.spy].Exchange

        while not exchange.DateIsOpen(datetime.combine(candidate, time.min)):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason):
        if self._held_contract is None or self._exit_order_id is not None:
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self._held_contract):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id, "Replacing existing exit order.")

        ticket = self.MarketOrder(self._held_contract, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {self._held_contract.Value}; {reason}.")

    def _liquidate_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0 or self._equity_cleanup_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -spy_quantity)
        self._equity_cleanup_order_id = ticket.OrderId
        self.Debug("Unexpected SPY exercise/assignment position detected; liquidation submitted.")

    def _option_position_exists(self):
        if self._held_contract is not None and self.Portfolio[self._held_contract].Invested:
            return True

        if self._entry_symbol is not None and self.Portfolio[self._entry_symbol].Invested:
            return True

        return False

    def OnOrderEvent(self, order_event):
        if self._entry_symbol is not None and order_event.Symbol == self._entry_symbol:
            if order_event.Status == OrderStatus.Filled:
                self._held_contract = order_event.Symbol
                self._held_expiry = order_event.Symbol.ID.Date.date()
                self._entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self._held_contract.Value} at {self._entry_price:.2f}."
                )
                self._entry_symbol = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry cancelled/invalid: {order_event.Symbol.Value}.")
                self._entry_symbol = None

        if self._exit_order_id is not None and order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol.Value} at {order_event.FillPrice:.2f}."
                )
                self._exit_order_id = None
                self._held_contract = None
                self._held_expiry = None
                self._entry_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._exit_order_id = None

        if (
            self._equity_cleanup_order_id is not None
            and order_event.OrderId == self._equity_cleanup_order_id
            and order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid)
        ):
            self._equity_cleanup_order_id = None
