        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=180))
        )

        self.close_window = RollingWindow[float](21)
        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol, self.five_minute_consolidator
        )

        self.pending_entry_time = None
        self.entry_order_id = None
        self.exit_order_id = None

        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.block_entries_on_date = None

    def OnFiveMinuteBar(self, sender, bar):
        # Only actual consolidated bars update the rolling window.
        self.close_window.Add(float(bar.Close))

        if self.close_window.Count < 21:
            return

        current_fast = sum(self.close_window[i] for i in range(5)) / 5.0
        current_slow = sum(self.close_window[i] for i in range(20)) / 20.0
        prior_fast = sum(self.close_window[i] for i in range(1, 6)) / 5.0
        prior_slow = sum(self.close_window[i] for i in range(1, 21)) / 20.0

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
            and
            (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        )

        if eligible_time and prior_fast <= prior_slow and current_fast > current_slow:
            # OnData processes this on the same Slice, where the option chain is available.
            self.pending_entry_time = end_time

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        if self.held_contract is not None:
            self.HandleExpirationSafety()
            self.HandleTimeStop()
            self.HandleProfitTarget(slice)
            self.ClearClosedPositionState()

        # A crossover signal is valid only on the Slice immediately following its close.
        if self.pending_entry_time is not None:
            if self.Time == self.pending_entry_time:
                self.TryEnterFromCurrentSlice(slice)
            elif self.Time > self.pending_entry_time:
                self.pending_entry_time = None

    def TryEnterFromCurrentSlice(self, slice):
        self.pending_entry_time = None

        if self.block_entries_on_date == self.Time.date():
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        if self.Portfolio[self.spy_symbol].Invested:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped; no SPY option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Entry skipped; no expiry at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
        ]

        if not calls:
            self.Debug(f"{self.Time}: Entry skipped; no calls at selected expiry.")
            return

        # With no strike specified, select the closest available strike to raw SPY price.
        selected_contract = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - float(self.Securities[self.spy_symbol].Price)),
                float(contract.Strike)
            )
        )

        ticket = self.MarketOrder(selected_contract.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_expiry = selected_contract.Expiry

        self.Debug(
            f"{self.Time}: Entry submitted for {selected_contract.Symbol}, "
            f"expiry {selected_expiry}."
        )

    def HandleProfitTarget(self, slice):
        if self.entry_fill_price is None or self.exit_order_id is not None:
            return

        quote_bar = slice.QuoteBars.get(self.held_contract)
        if quote_bar is None or quote_bar.Bid is None or quote_bar.Ask is None:
            return

        bid = float(quote_bar.Bid.Close)
        ask = float(quote_bar.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self.SubmitExit("50% profit target reached")

    def HandleTimeStop(self):
        if self.exit_order_id is not None or self.held_expiry is None:
            return

        previous_trading_day = self.GetPreviousTradingDay(self.held_expiry.date())

        if (
            self.Time.date() == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self.SubmitExit("15:45 pre-expiration time stop")

    def HandleExpirationSafety(self):
        if self.exit_order_id is not None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry.date():
            self.block_entries_on_date = self.Time.date()
            self.SubmitExit("expiration safety liquidation")

    def SubmitExit(self, reason):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, "Replacing open exit order")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Exit submitted for {self.held_contract}; {reason}.")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity == 0:
            return

        self.block_entries_on_date = self.Time.date()

        if not self.Transactions.GetOpenOrders(self.spy_symbol):
            self.MarketOrder(self.spy_symbol, -quantity)
            self.Debug(
                f"{self.Time}: Unexpected SPY exercise/assignment position detected; "
                f"liquidating {quantity} shares."
            )

    def ClearClosedPositionState(self):
        if (
            self.held_contract is not None
            and not self.Portfolio[self.held_contract].Invested
            and self.entry_order_id is None
            and self.exit_order_id is None
        ):
            self.held_contract = None
            self.held_expiry = None
            self.entry_fill_price = None

    def GetPreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_order_id = None

                self.Debug(
                    f"{self.Time}: Entry filled for {self.held_contract} "
                    f"at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.held_expiry = None
                self.Debug(f"{self.Time}: Entry order did not fill: {order_event.Status}.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled for {order_event.Symbol} "
                    f"at {float(order_event.FillPrice):.2f}."
                )
                self.exit_order_id = None

                if self.held_contract is not None and not self.Portfolio[self.held_contract].Invested:
                    self.held_contract = None
                    self.held_expiry = None
                    self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None
