        self._slow = SimpleMovingAverage(20)

        # Minute SPY data starts at 09:30, so this produces regular-session
        # five-minute bars ending at 09:35, 09:40, 09:45, etc.
        self._five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self._five_minute_consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self._spy, self._five_minute_consolidator)

        self._entry_signal_time = None
        self._entry_ticket = None
        self._exit_ticket = None
        self._spy_liquidation_ticket = None

        self._held_contract = None
        self._entry_price = None
        self._expiration_date = None
        self._entry_blackout_date = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        # A signal is valid only in the Slice in which its five-minute bar closed.
        if self._entry_signal_time is not None and self._entry_signal_time < self.Time:
            self._entry_signal_time = None

        self._handle_expiration_protection()
        self._handle_time_stop()
        self._handle_profit_target(data)

        if self._entry_signal_time == self.Time:
            self._entry_signal_time = None
            self._submit_entry(data)

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        previous_fast = self._fast.Current.Value
        previous_slow = self._slow.Current.Value
        averages_were_ready = self._fast.IsReady and self._slow.IsReady

        self._fast.Update(bar.EndTime, bar.Close)
        self._slow.Update(bar.EndTime, bar.Close)

        if not averages_were_ready:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self._fast.Current.Value > self._slow.Current.Value
        )

        bar_end_time = bar.EndTime.time()
        entry_window = time(9, 45) <= bar_end_time <= time(14, 30)

        if bullish_cross and entry_window:
            self._entry_signal_time = bar.EndTime

    def _submit_entry(self, data: Slice):
        if self._entry_blackout_date == self.Time.date():
            return

        if self._has_option_position() or self._order_is_open(self._entry_ticket):
            return

        if self._order_is_open(self._exit_ticket):
            return

        chain = data.OptionChains.get(self._option_symbol, None)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped; no SPY option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_expiries = sorted(
            {contract.Expiry.date() for contract in chain if contract.Expiry.date() >= minimum_expiry}
        )

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Entry skipped; no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        calls = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug(f"{self.Time}: Entry skipped; selected expiration has no calls.")
            return

