        # deterministically, preferring the lower strike in an exact tie.
        contract = min(
            calls,
            key=lambda c: (abs(c.Strike - underlying_price), c.Strike, str(c.Symbol))
        )

        self._expiration_date = selected_expiry
        self._entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug(
            f"{self.Time}: Submitted entry for {contract.Symbol} "
            f"(expiry {selected_expiry}, strike {contract.Strike})."
