            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(0), timedelta(days=365))
        )

        self._five_minute_closes = []
        self._pending_bullish_signal = False

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_contract = None
        self._entry_price = None
        self._block_entries_on = None

        consolidator = TradeBarConsolidator(self._five_minute_calendar)
        consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def _five_minute_calendar(self, timestamp):
        """Creates NY-clock-aligned regular-session five-minute buckets."""
        session_open = datetime.combine(timestamp.date(), time(9, 30))
        elapsed_seconds = max(0, int((timestamp - session_open).total_seconds()))
        bucket_start = session_open + timedelta(
            minutes=5 * (elapsed_seconds // 300)
        )
        return CalendarInfo(bucket_start, timedelta(minutes=5))

    def _on_five_minute_bar(self, sender, bar):
        previous_fast = None
        previous_slow = None

        if len(self._five_minute_closes) == 20:
            previous_fast = sum(self._five_minute_closes[-5:]) / 5.0
            previous_slow = sum(self._five_minute_closes) / 20.0

        self._five_minute_closes.append(float(bar.Close))
        if len(self._five_minute_closes) > 20:
            self._five_minute_closes.pop(0)

        if previous_fast is None or len(self._five_minute_closes) < 20:
            return

        current_fast = sum(self._five_minute_closes[-5:]) / 5.0
        current_slow = sum(self._five_minute_closes) / 20.0
        bar_end_time = bar.EndTime.time()

        if (time(9, 45) <= bar_end_time <= time(14, 30)
                and previous_fast <= previous_slow
                and current_fast > current_slow):
            self._pending_bullish_signal = True

    def OnData(self, slice):
        self._liquidate_unexpected_spy_position()
        self._process_expiration_protection()
        self._process_option_exit(slice)

        if self._pending_bullish_signal:
            self._pending_bullish_signal = False
            self._try_enter(slice)

    def _try_enter(self, slice):
        if self._block_entries_on == self.Time.date():
            return

        if self._has_open_entry_order() or self._has_option_holding():
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible_contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible_contracts:
            self.Debug(f"{self.Time}: Entry skipped: no eligible SPY calls with >= 7 DTE.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible_contracts)
        expiration_calls = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == selected_expiry
        ]

        if not expiration_calls:
            self.Debug(f"{self.Time}: Entry skipped: no calls at selected expiration.")
            return

        # No strike rule was supplied, so select the nearest strike to raw SPY price.
        underlying_price = float(self.Securities[self.spy].Price)
        selected = min(
            expiration_calls,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: Submitted entry for 1 {selected.Symbol} "
            f"(expiry {selected.Expiry.date()}, strike {selected.Strike})."
        )

    def _process_option_exit(self, slice):
        if not self._has_option_holding() or self._has_open_exit_order():
            return

        holding = self.Portfolio[self._held_contract]
        expiry = self._held_contract.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry)

        if (self.Time.date() == previous_trading_day
                and self.Time.time() == time(15, 45)):
            self._submit_exit("15:45 pre-expiration time stop")
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            return

        chain = slice.OptionChains[self.option_symbol]
        contract = next(
            (candidate for candidate in chain
             if candidate.Symbol == self._held_contract),
            None
        )

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self._entry_price is not None and midpoint >= 1.50 * self._entry_price:
            self._submit_exit(
                f"50% profit target; midpoint {midpoint:.2f}, "
                f"entry {self._entry_price:.2f}"
            )

    def _process_expiration_protection(self):
        if not self._has_option_holding():
            return

        expiry = self._held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self._block_entries_on = self.Time.date()
            self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if not self._has_option_holding() or self._has_open_exit_order():
            return

        if self._exit_ticket is not None:
            self._exit_ticket.Cancel("Replacing open exit order.")

        quantity = -self.Portfolio[self._held_contract].Quantity
        if quantity != 0:
            self._exit_ticket = self.MarketOrder(self._held_contract, quantity)
            self.Debug(f"{self.Time}: Submitted exit for {self._held_contract}: {reason}.")

    def _liquidate_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self._block_entries_on = self.Time.date()
            self.MarketOrder(self.spy, -spy_quantity)
            self.Debug(
                f"{self.Time}: Unexpected SPY position from exercise/assignment; "
                f"submitted liquidation for {spy_quantity} shares."
            )

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def _has_option_holding(self):
        return (
            self._held_contract is not None
            and self.Portfolio[self._held_contract].Quantity != 0
        )

    def _has_open_entry_order(self):
        if self._entry_ticket is None:
            return False

        return self._entry_ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def _has_open_exit_order(self):
        if self._exit_ticket is None:
            return False

        return self._exit_ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def OnOrderEvent(self, order_event):
        if self._entry_ticket is not None and order_event.OrderId == self._entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self._held_contract = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self._entry_ticket = None
                self.Debug(
                    f"{self.Time}: Entry filled for {order_event.Symbol} "
                    f"at {self._entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: Entry order was {order_event.Status}.")
                self._entry_ticket = None

        if self._exit_ticket is not None and order_event.OrderId == self._exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled for {order_event.Symbol} "
                    f"at {float(order_event.FillPrice):.2f}."
                )
                self._exit_ticket = None
                if not self.Portfolio[order_event.Symbol].Invested:
                    self._held_contract = None
                    self._entry_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: Exit order was {order_event.Status}.")
                self._exit_ticket = None
