        current_slow = sum(self._closes) / 20.0

        crossed_up = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end = bar.EndTime
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if crossed_up and eligible_time:
            self._pending_entry_time = bar_end

    def OnData(self, data):
        today = self.Time.date()

        # Never treat an exercise/assignment-created SPY position as a strategy entry.
        if self.Portfolio[self.spy].Quantity != 0:
            if not self._has_open_order_for_symbol(self.spy):
                quantity = -self.Portfolio[self.spy].Quantity
                self.MarketOrder(self.spy, quantity)
                self.Debug(
                    f"{self.Time} unexpected SPY exercise/assignment position; "
                    f"submitted liquidation for {quantity} shares"
                )

        # If an option survives to its expiration date, liquidate and block new entries.
        if self._held_contract is not None:
            expiry_date = self._held_contract.ID.Date.date()
