            if not self._is_order_open(self._exit_order_id):
                self._held_contract = None
                self._entry_price = None
                self._exit_order_id = None
            return

        # Scheduled time stop is independent of quote availability.
        expiry_date = self._held_contract.ID.Date.date()
        if (
            today == self._previous_spy_trading_day(expiry_date)
            and self.Time.time() == time(15, 45)
