        selected = min(
            calls,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        self._entry_order_id = None
        ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_order_id = ticket.OrderId

        self.Debug(
            f"{self.Time} submitted entry: 1 {selected.Symbol} "
            f"expiry {selected.Expiry.date()} strike {selected.Strike}"
        )

    def _submit_exit(self, reason):
        if (
            self._held_contract is None
            or not self.Portfolio[self._held_contract].Invested
            or self._is_order_open(self._exit_order_id)
        ):
            return

        # Ensure no other exit order remains active for this contract.
        for order in self.Transactions.GetOpenOrders(self._held_contract):
            self.Transactions.CancelOrder(order.Id, "Replacing with market exit")

        quantity = -self.Portfolio[self._held_contract].Quantity
        ticket = self.MarketOrder(self._held_contract, quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time} submitted exit: {quantity} {self._held_contract}; {reason}"
        )

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self._entry_order_id:
            if order_event.FillQuantity > 0 and self._held_contract is None:
                self._held_contract = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time} entry filled: {order_event.Symbol} "
                    f"at {order_event.FillPrice:.2f}"
                )

            if order_event.Status == OrderStatus.Filled:
                self._entry_order_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._entry_order_id = None
                self.Debug(f"{self.Time} entry order did not fill: {order_event.Status}")

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time} exit filled: {order_event.Symbol} "
                    f"at {order_event.FillPrice:.2f}"
                )
                self._held_contract = None
                self._entry_price = None
                self._exit_order_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._exit_order_id = None

    def _contract_in_current_slice(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time.min)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _is_order_open(self, order_id):
        if order_id is None:
            return False
        return any(
            order.Id == order_id
            for order in self.Transactions.GetOpenOrders()
        )

    def _has_open_order_for_symbol(self, symbol):
        return any(
            order.Symbol == symbol
            for order in self.Transactions.GetOpenOrders()
        )
