        self._option.SetFilter(
            lambda universe: universe.Strikes(-100, 100).Expiration(
                timedelta(days=0), timedelta(days=90)
            )
        )

        self._fast = SimpleMovingAverage(5)
        self._slow = SimpleMovingAverage(20)

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self._spy, consolidator)

        self._pending_entry_signal = False
        self._pending_signal_end = None

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._expiration_date = None
        self._no_entry_date = None
        self._spy_cleanup_ticket = None

    def OnData(self, slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_protection()
        self._handle_time_exit()

        if self._pending_entry_signal:
            self._pending_entry_signal = False
            self._try_enter(slice)

        self._handle_profit_target(slice)

    def _on_five_minute_bar(self, sender, bar):
        fast_was_ready = self._fast.IsReady
        slow_was_ready = self._slow.IsReady
        previous_fast = self._fast.Current.Value
        previous_slow = self._slow.Current.Value

        self._fast.Update(bar.EndTime, bar.Close)
        self._slow.Update(bar.EndTime, bar.Close)

        if not (fast_was_ready and slow_was_ready and self._fast.IsReady and self._slow.IsReady):
            return

        end_clock = bar.EndTime.time()
        eligible_time = time(9, 45) <= end_clock <= time(14, 30)
